args.sql:
-- Check if equipRef in Communication matches equip_ref in PowerBattery
SELECT COUNT(*) FROM "Communication" c 
JOIN "PowerBattery" pb ON c."equipRef" = pb."equip_ref";

SELECT COUNT(DISTINCT CASE WHEN c."equipRef" = pb."equip_ref" THEN c."equipRef" END) as overlap
FROM "CabinEnvironment" c
JOIN "PowerBattery" pb ON c."equipRef" = pb."equip_ref";

-- Check if CabinEnvironment has any unique equipRef not in Communication
SELECT COUNT(*) FROM "CabinEnvironment" c 
WHERE c."equipRef" NOT IN (SELECT "equipRef" FROM "Communication");

-- Check if any equipment table has both equipRef and loc_link that we can use
SELECT 'CabinEnvironment' as tbl, COUNT(*) FROM "CabinEnvironment" WHERE "loc_link" IS NOT NULL AND "equipRef" IS NOT NULL
UNION ALL SELECT 'Communication', COUNT(*) FROM "Communication" WHERE "loc_link" IS NOT NULL AND "equipRef" IS NOT NULL;

-- Check if CabinEnvironment equipRef also links to PowerBattery
SELECT COUNT(*) FROM "CabinEnvironment" c
JOIN "PowerBattery" pb ON c."equipRef" = pb."equip_ref";

-- Check overlap between Communication and CabinEnvironment equipRef
SELECT COUNT(*) FROM "Communication" c
JOIN "CabinEnvironment" ce ON c."equipRef" = ce."equipRef";

SELECT COUNT(*) FROM "WeatherAndStructure" w
JOIN "OperationMaintenance" om ON w."opmaint_link" = om."OP_MAINT_ID"
JOIN "Equipment" e ON om."equipRef" = e."EQUIP_CODE";

-- Check overlap between Communication and WeatherAndStructure (via OperationMaintenance) equipment
SELECT COUNT(*) FROM "Communication" c
JOIN "OperationMaintenance" om ON c."equipRef" = om."equipRef";

SELECT COUNT(*) FROM "WeatherAndStructure" w
JOIN "OperationMaintenance" om ON w."opmaint_link" = om."OP_MAINT_ID"
WHERE om."equipRef" NOT IN (SELECT "equipRef" FROM "Communication");
